/**
 * Phase R4: Data path resolver.
 * Scans translated code for file-loading calls, extracts path arguments,
 * detects the common base data directory, and generates path-resolution code.
 */

import { readdirSync, readFileSync, statSync, mkdirSync, copyFileSync, existsSync } from "node:fs";
import { join, dirname, posix, relative } from "node:path";

export interface DataPathResult {
  basePath: string;
  allPaths: string[];
  generatedCode: string;
}

/** Functions that load files (C/C++ and library-specific) */
const FILE_LOADING_FUNCTIONS = [
  "fopen", "freopen", "open",
  "IMG_Load", "IMG_LoadTexture", "IMG_Load_RW",
  "Mix_LoadWAV", "Mix_LoadMUS", "Mix_LoadWAV_RW",
  "TTF_OpenFont", "TTF_OpenFontIndex",
  "SDL_LoadBMP", "SDL_LoadWAV", "SDL_RWFromFile",
  "LoadFile", "LoadImage", "LoadTexture", "LoadSound", "LoadFont",
  "CGraphic::Load", "CGraphic::New", "CGraphic::Get",
  "CPlayerColorGraphic::New",
  "CMusic::Load", "CSample::Load",
  "LibraryFileName",
  "readFile", "readFileSync",
  "load", "dofile", "loadfile", "require",
  "fstream", "ifstream", "ofstream",
];

/**
 * Scan all translated .ts files for file-loading function calls,
 * extract string literal arguments, and detect the base data path.
 */
export function resolveDataPaths(projectDir: string): DataPathResult {
  const allCode = readAllTsCode(projectDir);
  const paths = extractFilePaths(allCode);

  if (paths.length === 0) {
    return {
      basePath: "./data",
      allPaths: [],
      generatedCode: generatePathCode("./data"),
    };
  }

  const basePath = detectBasePath(paths);

  return {
    basePath,
    allPaths: paths,
    generatedCode: generatePathCode(basePath),
  };
}

/**
 * Extract all string literal arguments from known file-loading function calls.
 */
function extractFilePaths(code: string): string[] {
  const paths = new Set<string>();

  // Match function calls with string literal arguments
  for (const funcName of FILE_LOADING_FUNCTIONS) {
    // Escape special chars in function name for regex
    const escaped = funcName.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    // Match funcName("path") or funcName('path')
    const re = new RegExp(`${escaped}\\s*\\(\\s*["']([^"']+)["']`, "g");
    for (const match of code.matchAll(re)) {
      const p = match[1];
      // Filter out obvious non-paths
      if (p.length > 2 && !p.startsWith("http") && !p.startsWith("//") && !p.includes("\\n")) {
        paths.add(normalizePathSep(p));
      }
    }
  }

  // Also catch string concatenation patterns like: path + "/file.png"
  // and template literals used with these functions
  const concatRe = /["']([^"']*\.(png|jpg|jpeg|bmp|gif|wav|mp3|ogg|ttf|otf|lua|txt|cfg|ini|dat|xml|json))["']/g;
  for (const match of code.matchAll(concatRe)) {
    const p = match[1];
    if (p.length > 2) paths.add(normalizePathSep(p));
  }

  return [...paths].sort();
}

/**
 * Detect the common base path from a list of file paths.
 */
function detectBasePath(paths: string[]): string {
  // Common prefixes to look for
  const knownPrefixes = [
    "data/", "./data/", "../data/",
    "assets/", "./assets/", "../assets/",
    "resources/", "./resources/", "../resources/",
    "res/", "./res/",
    "media/", "./media/",
    "graphics/", "./graphics/",
    "gfx/", "./gfx/",
    "sounds/", "./sounds/",
    "sfx/", "./sfx/",
  ];

  // Count how many paths start with each known prefix
  let bestPrefix = "";
  let bestCount = 0;
  for (const prefix of knownPrefixes) {
    const count = paths.filter(p => p.startsWith(prefix) || p.includes("/" + prefix)).length;
    if (count > bestCount) { bestCount = count; bestPrefix = prefix; }
  }

  if (bestPrefix) {
    return "./" + bestPrefix.replace(/\/$/, "");
  }

  // Try to find the longest common prefix among all paths
  if (paths.length >= 2) {
    const parts0 = paths[0].split("/");
    let commonLen = 0;
    outer: for (let i = 0; i < parts0.length - 1; i++) {
      for (const p of paths) {
        const parts = p.split("/");
        if (i >= parts.length || parts[i] !== parts0[i]) break outer;
      }
      commonLen = i + 1;
    }
    if (commonLen > 0) {
      return "./" + parts0.slice(0, commonLen).join("/");
    }
  }

  return "./data";
}

function generatePathCode(basePath: string): string {
  return `// Data path resolution — generated by src2ts
(globalThis as any).StratagusLibPath = ${JSON.stringify(basePath)};

function LibraryFileName(name: string): string {
  const base = (globalThis as any).StratagusLibPath ?? ${JSON.stringify(basePath)};
  // Normalize: strip leading ./ from name, ensure no double slashes
  const clean = name.replace(/^\\.[\\/\\/]/, "");
  return base + "/" + clean;
}
(globalThis as any).LibraryFileName = LibraryFileName;
`;
}

/**
 * Copy discovered asset files to the output directory, preserving relative paths.
 * Used by Node.js targets to ensure data files are available at runtime.
 */
export function copyAssets(sourcePaths: string[], sourceBase: string, outputDir: string): number {
  let copied = 0;
  for (const srcPath of sourcePaths) {
    const fullSrc = join(sourceBase, srcPath);
    if (!existsSync(fullSrc)) continue;
    try {
      if (!statSync(fullSrc).isFile()) continue;
    } catch { continue; }
    const relPath = relative(sourceBase, fullSrc);
    const dest = join(outputDir, relPath);
    const destDir = dirname(dest);
    mkdirSync(destDir, { recursive: true });
    try {
      copyFileSync(fullSrc, dest);
      copied++;
    } catch { /* skip unreadable files */ }
  }
  return copied;
}

function normalizePathSep(p: string): string {
  return p.replace(/\\\\/g, "/").replace(/\\/g, "/");
}

function readAllTsCode(projectDir: string): string {
  const parts: string[] = [];
  function walk(dir: string): void {
    try {
      for (const entry of readdirSync(dir)) {
        if (["node_modules", "dist", "shims", "runtime", ".git"].includes(entry)) continue;
        const full = join(dir, entry);
        if (statSync(full).isDirectory()) { walk(full); continue; }
        if (!entry.endsWith(".ts") || entry.endsWith(".d.ts")) continue;
        try { parts.push(readFileSync(full, "utf-8")); } catch { /* skip */ }
      }
    } catch { /* unreadable dir */ }
  }
  walk(projectDir);
  return parts.join("\n");
}
